"""Persian RTL workspace for marketing offer plans."""
from fastapi import APIRouter, Response
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["CRM marketing offer plan workspace"], include_in_schema=False)
_HEADERS = {
    "Cache-Control": "no-store",
    "Content-Security-Policy": "default-src 'self'; script-src 'self'; style-src 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'",
    "Referrer-Policy": "no-referrer", "X-Content-Type-Options": "nosniff",
}
_PAGE = """<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>برنامه‌ریزی پیشنهاد بازاریابی | فانل CRM</title><style>
:root{font-family:Tahoma,Arial,sans-serif;color:#182638;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}header{background:#12334a;color:white;padding:20px max(16px,calc((100vw - 1080px)/2))}main{max-width:1080px;margin:24px auto;padding:0 16px 48px}h1{font-size:clamp(23px,4vw,32px)}h2{font-size:19px}.panel{background:white;border:1px solid #e0e7ef;border-radius:14px;padding:20px;margin:16px 0;box-shadow:0 5px 18px #142d420d}.grid,.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}label{display:grid;gap:6px;font-size:13px;color:#405367}select,input,textarea,button{font:inherit;min-height:42px;border:1px solid #cbd6e0;border-radius:8px;padding:8px 10px;background:white;color:#182638}textarea{min-height:82px;resize:vertical}button{background:#1578a8;color:white;border:0;font-weight:bold;cursor:pointer}.actions{display:flex;gap:10px;margin-top:14px}.card{border:1px solid #dce5ed;border-radius:10px;padding:14px}.muted{color:#687b8d;font-size:13px;line-height:1.8}.tag{display:inline-block;background:#fff4dd;color:#77520b;border-radius:99px;padding:4px 9px;font-size:12px}#status{min-height:24px}@media(max-width:560px){.panel{padding:15px}}
</style><script src="/assets/crm-offer-plan-workspace.js" defer></script></head><body><header><strong>فانل CRM</strong></header><main>
<h1>برنامه‌ریزی پیشنهاد بازاریابی</h1><p class="muted">هدف، محصول، مخاطب، کانال، زمان و معیار موفقیت را برای پیشنهاد ثبت کنید. نوع پیشنهاد و شرط‌ها برای هر کسب‌وکار آزادند. این صفحه فقط پیش‌نویس می‌سازد؛ قیمت، تخفیف، صندوق یا سامانهٔ مقصد را تغییر نمی‌دهد.</p><p id="status" role="status" aria-live="polite"></p>
<section class="panel"><h2>محدوده</h2><label>فضای کاری<select id="workspace" required></select></label><label>واحد سازمانی<select id="organization" required></select></label></section>
<section class="panel"><h2 id="form-title">پیش‌نویس تازه</h2><form id="form"><div class="grid">
<label>نام پیشنهاد<input id="name" maxlength="160" required></label><label>نوع پیشنهاد (قابل تنظیم)<input id="offer-type" maxlength="80" placeholder="مثلاً بستهٔ خدمات یا مشوق وفاداری" required></label>
<label>محصول یا خدمت<select id="catalog-item"><option value="">بدون پیوند به کاتالوگ</option></select></label><label>کمپین مرتبط<select id="campaign"><option value="">بدون پیوند به کمپین</option></select></label>
<label>کانال<input id="channel" maxlength="80" placeholder="آنلاین، فروشگاه، تماس، میدانی…" required></label><label>منطقه یا شعبه<input id="location" maxlength="250"></label>
<label>شروع<input id="starts" type="datetime-local"></label><label>پایان<input id="ends" type="datetime-local"></label>
</div><label>هدف<textarea id="objective" maxlength="2000" required></textarea></label><label>مخاطب هدف<textarea id="audience" maxlength="1000" required></textarea></label><label>شرط استفاده<textarea id="eligibility" maxlength="4000"></textarea></label><label>شاخص موفقیت<input id="success-metric" maxlength="500" required></label>
<div class="actions"><button id="submit" type="submit">ثبت پیش‌نویس</button><button id="cancel-edit" type="button" hidden>لغو ویرایش</button></div></form></section>
<section class="panel" id="scenario-panel" hidden><h2>مقایسهٔ سناریوهای اقتصادی</h2><p id="scenario-plan-name" class="muted"></p><form id="scenario-form"><div class="grid"><label>نام سناریو<input id="scenario-name" maxlength="120" required></label><label>اندازهٔ مخاطب<input id="scenario-audience" type="number" min="0" required></label><label>نرخ استفادهٔ مورد انتظار (درصد)<input id="scenario-rate" type="number" min="0" max="100" step="0.01" required></label><label>نسخهٔ قیمت مرجع<select id="scenario-price"><option value="">بدون قیمت مرجع</option></select></label><label>ارزش پیشنهاد برای هر استفاده<input id="scenario-value" type="number" min="0" step="0.01"></label><label>بودجهٔ کمپین<input id="scenario-budget" type="number" min="0" step="0.01"></label><label>ارز بودجه<input id="scenario-currency" maxlength="3" placeholder="USD"></label></div><label>فرض‌ها<textarea id="scenario-assumptions" maxlength="2000" required></textarea></label><div class="actions"><button type="submit">ثبت سناریوی تغییرناپذیر</button></div></form><p class="muted">این اعداد برآورد مبتنی بر فرض هستند. به‌دلیل نبود دادهٔ معتبر هزینه، حاشیهٔ سود محاسبه نمی‌شود.</p><div id="scenarios" class="cards"></div></section><section class="panel"><h2>پیش‌نویس‌ها</h2><div id="plans" class="cards"></div></section></main></body></html>"""

_SCRIPT = r"""(() => {
const $=id=>document.getElementById(id),workspace=$("workspace"),organization=$("organization"),plans=$("plans"),status=$("status"),params=new URLSearchParams(location.search);let selected=null,scenarioPlan=null;
function msg(t,e=false){status.textContent=t||"";status.style.color=e?"#8b3b22":"#17613b"}function opt(s,v,t){const o=document.createElement("option");o.value=v;o.textContent=t;s.appendChild(o)}
async function api(path,method="GET",body,scope=true){const h={Accept:"application/json"};if(scope)h["X-Workspace-ID"]=workspace.value;if(body!==undefined)h["Content-Type"]="application/json";const r=await fetch(path,{method,credentials:"same-origin",headers:h,body:body===undefined?undefined:JSON.stringify(body)});let d={};try{d=await r.json()}catch(_){}if(!r.ok)throw Error(d.detail||`عملیات ناموفق بود (${r.status}).`);return d}
function val(id){return $(id).value.trim()}function toIso(v){return v?new Date(v).toISOString():null}
async function loadRefs(){const units=await api("/api/v1/system/offer-plan-organization-units");organization.replaceChildren();opt(organization,"","واحد سازمانی را انتخاب کنید");units.forEach(x=>opt(organization,x.id,x.name));organization.value=units.find(x=>x.id===params.get("organization_unit_id"))?.id||units.find(x=>x.unit_type==="root")?.id||"";await loadOptions()}
async function loadOptions(){const item=$("catalog-item"),campaign=$("campaign");item.replaceChildren();opt(item,"","بدون پیوند به کاتالوگ");campaign.replaceChildren();opt(campaign,"","بدون پیوند به کمپین");if(!organization.value)return;try{const d=await api(`/api/v1/crm/catalog/items?organization_unit_id=${encodeURIComponent(organization.value)}&limit=200`);(d.items||[]).forEach(x=>opt(item,x.id,`${x.name} · ${x.code}`))}catch(_){}try{const d=await api(`/api/v1/crm/campaigns?organization_unit_id=${encodeURIComponent(organization.value)}&status=draft&limit=100`);(d.items||[]).forEach(x=>opt(campaign,x.id,x.name))}catch(_){}await loadPlans()}
function reset(){selected=null;$("form").reset();$("form-title").textContent="پیش‌نویس تازه";$("submit").textContent="ثبت پیش‌نویس";$("cancel-edit").hidden=true}
function edit(p){selected=p;$("form-title").textContent="ویرایش پیش‌نویس";$("submit").textContent="ذخیرهٔ نسخهٔ جدید";$("cancel-edit").hidden=false;$("name").value=p.name;$("offer-type").value=p.offer_type;$("catalog-item").value=p.catalog_item_id||"";$("campaign").value=p.campaign_id||"";$("channel").value=p.channel;$("location").value=p.location_scope||"";$("starts").value=p.starts_at?new Date(p.starts_at).toISOString().slice(0,16):"";$("ends").value=p.ends_at?new Date(p.ends_at).toISOString().slice(0,16):"";$("objective").value=p.objective;$("audience").value=p.audience_description;$("eligibility").value=p.eligibility_conditions||"";$("success-metric").value=p.success_metric;window.scrollTo({top:0,behavior:"smooth"})}
async function decide(plan,decision,comment){try{await api(`/api/v1/crm/offer-plans/${encodeURIComponent(plan.id)}/decision`,"POST",{expected_version:plan.version,decision,comment});await loadPlans();msg(decision==="approve"?"پیشنهاد در CRM تأیید شد؛ در کانال یا فروشگاه فعال نشده است.":"اصلاح پیشنهاد درخواست شد.")}catch(e){msg(e.message,true)}}
async function openScenarios(p){scenarioPlan=p;$("scenario-panel").hidden=false;$("scenario-plan-name").textContent=`${p.name} · نسخهٔ برنامه ${p.version}`;const prices=$("scenario-price");prices.replaceChildren();opt(prices,"","بدون قیمت مرجع");if(p.catalog_item_id){try{const d=await api(`/api/v1/crm/catalog/items/${encodeURIComponent(p.catalog_item_id)}/prices`);(d.items||[]).forEach(x=>opt(prices,x.version,`نسخه ${x.version} · ${x.amount} ${x.currency}`))}catch(e){msg(e.message,true)}}await loadScenarios();$("scenario-panel").scrollIntoView({behavior:"smooth"})}
async function loadScenarios(){const box=$("scenarios");box.replaceChildren();if(!scenarioPlan)return;const d=await api(`/api/v1/crm/offer-plans/${encodeURIComponent(scenarioPlan.id)}/scenarios`);(d.items||[]).forEach(x=>{const card=document.createElement("article");card.className="card";const title=document.createElement("strong");title.textContent=x.name;const details=document.createElement("p");details.className="muted";details.textContent=`استفادهٔ مورد انتظار: ${x.expected_uses} · درآمد مرجع: ${x.gross_reference_revenue??"—"} · ارزش پیشنهاد: ${x.planned_offer_value??"—"} · پس از پیشنهاد: ${x.revenue_after_offer??"—"} · وضعیت: ${x.economic_completeness} · حاشیهٔ سود: محاسبه نشده (دادهٔ هزینه موجود نیست)`;const assumptions=document.createElement("p");assumptions.className="muted";assumptions.textContent=`فرض‌ها: ${x.assumptions}`;card.append(title,details,assumptions);box.appendChild(card)})}
async function loadPlans(){const d=await api(`/api/v1/crm/offer-plans?organization_unit_id=${encodeURIComponent(organization.value)}`);plans.replaceChildren();(d.items||[]).forEach(p=>{const card=document.createElement("article");card.className="card";const name=document.createElement("strong");name.textContent=p.name;const tag=document.createElement("span");tag.className="tag";tag.textContent=`${p.status==="approved"?"تأییدشده":p.status==="changes_requested"?"نیازمند اصلاح":"پیش‌نویس"} · نسخه ${p.version}`;const info=document.createElement("p");info.className="muted";info.textContent=`${p.offer_type} · ${p.channel} · هدف: ${p.objective}`;const audience=document.createElement("p");audience.className="muted";audience.textContent=`مخاطب: ${p.audience_description}`;card.append(name,tag,info,audience);const scenarioButton=document.createElement("button");scenarioButton.type="button";scenarioButton.textContent="مقایسهٔ سناریوها";scenarioButton.addEventListener("click",()=>openScenarios(p).catch(e=>msg(e.message,true)));card.appendChild(scenarioButton);if(p.review_note){const note=document.createElement("p");note.className="muted";note.textContent=`یادداشت بازبینی: ${p.review_note}`;card.appendChild(note)}if(p.status!=="approved"){const editButton=document.createElement("button");editButton.type="button";editButton.textContent="ویرایش پیش‌نویس";editButton.addEventListener("click",()=>edit(p));card.appendChild(editButton);const comment=document.createElement("textarea");comment.maxLength=2000;comment.placeholder="یادداشت بازبینی (برای تصمیم الزامی است)";const approve=document.createElement("button");approve.type="button";approve.textContent="تأیید در CRM";approve.addEventListener("click",()=>decide(p,"approve",comment.value.trim()));const changes=document.createElement("button");changes.type="button";changes.textContent="درخواست اصلاح";changes.addEventListener("click",()=>decide(p,"request_changes",comment.value.trim()));card.append(comment,approve,changes)}plans.appendChild(card)});if(!plans.children.length){const p=document.createElement("p");p.className="muted";p.textContent="پیش‌نویسی برای این واحد ثبت نشده است.";plans.appendChild(p)}}
$("scenario-form").addEventListener("submit",async e=>{e.preventDefault();if(!scenarioPlan)return;const body={name:val("scenario-name"),audience_size:Number(val("scenario-audience")),expected_use_rate:Number(val("scenario-rate")),price_version:$("scenario-price").value?Number($("scenario-price").value):null,offer_value_per_use:val("scenario-value")||null,campaign_budget_amount:val("scenario-budget")||null,campaign_budget_currency:val("scenario-currency").toUpperCase()||null,assumptions:val("scenario-assumptions")};try{await api(`/api/v1/crm/offer-plans/${encodeURIComponent(scenarioPlan.id)}/scenarios`,"POST",body);$("scenario-form").reset();await loadScenarios();msg("سناریوی تغییرناپذیر ثبت شد.")}catch(e){msg(e.message,true)}});
$("form").addEventListener("submit",async e=>{e.preventDefault();if(!organization.value)return msg("واحد سازمانی را انتخاب کنید.",true);const body={organization_unit_id:organization.value,name:val("name"),objective:val("objective"),offer_type:val("offer-type"),catalog_item_id:$("catalog-item").value||null,audience_description:val("audience"),channel:val("channel"),location_scope:val("location")||null,starts_at:toIso($("starts").value),ends_at:toIso($("ends").value),eligibility_conditions:val("eligibility")||null,success_metric:val("success-metric"),campaign_id:$("campaign").value||null};try{if(selected){delete body.organization_unit_id;await api(`/api/v1/crm/offer-plans/${encodeURIComponent(selected.id)}`,"PATCH",{...body,expected_version:selected.version});msg("پیش‌نویس به نسخهٔ تازه به‌روزرسانی شد.")}else{await api("/api/v1/crm/offer-plans","POST",body);msg("پیش‌نویس پیشنهاد ثبت شد.")}reset();await loadPlans()}catch(err){msg(err.message,true)}});
$("cancel-edit").addEventListener("click",reset);organization.addEventListener("change",()=>loadOptions().catch(e=>msg(e.message,true)));workspace.addEventListener("change",()=>loadRefs().catch(e=>msg(e.message,true)));
async function init(){try{const spaces=await api("/api/v1/system/workspaces","GET",undefined,false);workspace.replaceChildren();opt(workspace,"","فضای کاری را انتخاب کنید");spaces.forEach(x=>opt(workspace,x.id,x.name));workspace.value=spaces.find(x=>x.id===params.get("workspace_id"))?.id||(spaces.length===1?spaces[0].id:"");if(workspace.value)await loadRefs()}catch(e){msg(e.message,true)}}init();
})();"""


@router.get("/workspace/crm-offer-plans", response_class=HTMLResponse)
async def crm_offer_plan_workspace_page() -> HTMLResponse:
    return HTMLResponse(_PAGE, headers=_HEADERS)


@router.get("/assets/crm-offer-plan-workspace.js")
async def crm_offer_plan_workspace_script() -> Response:
    return Response(_SCRIPT, media_type="application/javascript", headers={"Cache-Control": "no-store", "X-Content-Type-Options": "nosniff"})
